using Backend.Exceptions;using Backend.Models;using Backend.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace Backend.Controllers;[ApiController][Route("api/[controller]")][Authorize(Roles = "RH")]public class RolController : ControllerBase{    private readonly RolService _rolService;    public RolController(RolService rolService)    {        _rolService = rolService;    }    [HttpGet]    public async Task<IActionResult> ObtenerTodos([FromQuery] int skip = 0, [FromQuery] int take = 100)    {        var roles = await _rolService.GetRolesAsync(skip, take);        return Ok(roles);    }    [HttpGet("{id}")]    public async Task<IActionResult> ObtenerPorId(long id)    {        var rol = await _rolService.GetRolByIdAsync(id);        if (rol is null)            return NotFound(new { mensaje = $"No se encontró el rol con Id {id}." });        return Ok(rol);    }    [HttpPost]    public async Task<IActionResult> Crear([FromBody] CrearRolModel model)    {        try        {            var rol = await _rolService.CreateRolAsync(model);            return CreatedAtAction(                nameof(ObtenerPorId),                new { id = rol.Id },                rol);        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }    [HttpPut("{id}")]    public async Task<IActionResult> Actualizar(long id, [FromBody] ActualizarRolModel model)    {        try        {            var actualizado = await _rolService.UpdateRolAsync(id, model);            if (!actualizado)                return NotFound(new { mensaje = $"No se encontró el rol con Id {id}." });            return NoContent();        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }    [HttpDelete("{id}")]    public async Task<IActionResult> Eliminar(long id)    {        try        {            var eliminado = await _rolService.DeleteRolAsync(id);            if (!eliminado)                return NotFound(new { mensaje = $"No se encontró el rol con Id {id}." });            return NoContent();        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }}